<?php require '../includes/app.php';require 'layout.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check();$email=trim($_POST['email']??'');$q=db()->prepare('SELECT * FROM users WHERE email=?');$q->execute([$email]);$u=$q->fetch();if($u&&strtotime($u['locked_until']??'1970-01-01')>time())$error='Please wait 15 minutes before trying again.';elseif($u&&password_verify($_POST['password']??'',$u['password'])){db()->prepare('UPDATE users SET failed_attempts=0,locked_until=NULL WHERE id=?')->execute([$u['id']]);session_regenerate_id(true);$_SESSION['admin']=$u['id'];header('Location: index.php');exit;}else{if($u)db()->prepare('UPDATE users SET failed_attempts=failed_attempts+1,locked_until=IF(failed_attempts>=5,DATE_ADD(NOW(),INTERVAL 15 MINUTE),NULL) WHERE id=?')->execute([$u['id']]);$error='Invalid login.';}}top('Admin login');?><p><?=e($error)?></p><form method="post"><?=token()?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn-company">Log in</button></form><?php bottom();?>